#include <string>
#include <utility>
#include <vector>

// After std::move(s), s is in a 'valid but unspecified' state. Reading
// its value isn't UB per se, but the value is implementation-defined and
// real code occasionally relies on a specific value (typically empty).
void consume_and_log(std::string& s, std::vector<std::string>& sink) {
    sink.push_back(std::move(s));
    // Bug? The author expected `s` to be empty here, but the standard
    // doesn't guarantee it. libstdc++ leaves it empty; libc++ might too,
    // but msvc's stdlib is silent on the matter.
    if (s.size() > 0) {
        // This branch is observable but its frequency is implementation-defined.
        sink.back().append(":carry-over:");
        sink.back().append(s);
    }
}
